import{_ as n,a as p,i as a,j as l,k as c,l as o,m as e,n as t,o as r,b as i,c as d,d as m,e as w,f as h,g as u,h as _}from"./chunks/mmad_950.CGM8UhNP.js";import{_ as f}from"./chunks/zn_half.BVtiqcaL.js";import{_ as g,a as C}from"./chunks/col_major.W_ZHRP2F.js";import{_ as A,o as L,a as v,b}from"./app.DKoEZOcr.js";const k="/ascendc.github.io/pr/5487/assets/hier_layout.Bxss4b61.png",G=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"编程模型","link":"/guide/programming_guide/programming_model/programming_model"},{"text":"AI Core SIMD编程","link":"/guide/programming_guide/programming_model/ai_core_simd_programming/ai_core_simd_programming"},{"text":"基于Tensor的C++编程","link":"/guide/programming_guide/programming_model/ai_core_simd_programming/cpp_tensor_programming/cpp_tensor_programming_overview"},{"text":"Cube矩阵计算编程","link":"/guide/programming_guide/programming_model/ai_core_simd_programming/cpp_tensor_programming/cube_matrix_computation"}]},"headers":[],"relativePath":"guide/programming_guide/programming_model/ai_core_simd_programming/cpp_tensor_programming/cube_matrix_computation.md","filePath":"guide/programming_guide/programming_model/ai_core_simd_programming/cpp_tensor_programming/cube_matrix_computation.md","outlineHeaders":[{"level":2,"title":"矩阵编程的基本步骤","slug":"矩阵编程的基本步骤","link":"#矩阵编程的基本步骤"},{"level":2,"title":"矩阵计算内存管理","slug":"矩阵计算内存管理","link":"#矩阵计算内存管理"},{"level":3,"title":"矩阵计算内存申请","slug":"矩阵计算内存申请","link":"#矩阵计算内存申请"},{"level":3,"title":"矩阵计算内存布局","slug":"矩阵计算内存布局","link":"#矩阵计算内存布局"},{"level":3,"title":"关键分形格式详解","slug":"关键分形格式详解","link":"#关键分形格式详解"},{"level":4,"title":"ND格式（N-Dimension）","slug":"ND格式（N-Dimension）","link":"#ND格式（N-Dimension）"},{"level":4,"title":"Nz格式","slug":"Nz格式","link":"#Nz格式"},{"level":4,"title":"Zz格式","slug":"Zz格式","link":"#Zz格式"},{"level":4,"title":"Zn格式","slug":"Zn格式","link":"#Zn格式"},{"level":3,"title":"格式转换","slug":"格式转换","link":"#格式转换"},{"level":2,"title":"基础Tensor编程范式","slug":"基础Tensor编程范式","link":"#基础Tensor编程范式"},{"level":3,"title":"矩阵数据搬入","slug":"矩阵数据搬入","link":"#矩阵数据搬入"},{"level":4,"title":"GM2L1 随路转换ND2NZ搬运","slug":"GM2L1-随路转换ND2NZ搬运","link":"#GM2L1-随路转换ND2NZ搬运"},{"level":4,"title":"L12L0 数据搬运","slug":"L12L0-数据搬运","link":"#L12L0-数据搬运"},{"level":3,"title":"矩阵数据搬出","slug":"矩阵数据搬出","link":"#矩阵数据搬出"},{"level":3,"title":"矩阵计算","slug":"矩阵计算","link":"#矩阵计算"},{"level":3,"title":"同步机制","slug":"同步机制","link":"#同步机制"},{"level":3,"title":"基于基础Tensor的矩阵计算编程示例","slug":"基于基础Tensor的矩阵计算编程示例","link":"#基于基础Tensor的矩阵计算编程示例"},{"level":2,"title":"扩展Tensor编程范式","slug":"扩展Tensor编程范式","link":"#扩展Tensor编程范式"},{"level":3,"title":"Layout的层次化表述","slug":"Layout的层次化表述","link":"#Layout的层次化表述"},{"level":3,"title":"矩阵计算中的分形表达","slug":"矩阵计算中的分形表达","link":"#矩阵计算中的分形表达"},{"level":3,"title":"Layout的构造","slug":"Layout的构造","link":"#Layout的构造"},{"level":3,"title":"基于Layout的Tensor表达","slug":"基于Layout的Tensor表达","link":"#基于Layout的Tensor表达"},{"level":3,"title":"矩阵搬运和计算","slug":"矩阵搬运和计算","link":"#矩阵搬运和计算"},{"level":3,"title":"基于扩展Tensor的矩阵计算示例","slug":"基于扩展Tensor的矩阵计算示例","link":"#基于扩展Tensor的矩阵计算示例"}],"lastUpdated":1788401590000}'),B={name:"guide/programming_guide/programming_model/ai_core_simd_programming/cpp_tensor_programming/cube_matrix_computation.md"};function N(y,s,P,M,S,T){return L(),v("div",null,[...s[0]||(s[0]=[b(`<div><article class="markdown-body"><h1>Cube矩阵计算编程<span id="ZH-CN_TOPIC_0000002600000003"></span></h1><p>本文介绍如何在Ascend C中使用C++ Tensor编程API编写基于L1 Buffer、L0A Buffer等片上存储的<strong>矩阵计算代码</strong>。</p><p>AI Core包含Vector计算单元（部署于AIV核）和Cube计算单元（部署于AIC核）。Cube计算单元专用于执行矩阵运算，直接访问的专用缓存如下：L0A Buffer存储左矩阵，L0B Buffer存储右矩阵，L0C Buffer存储初始累加值及矩阵计算结果。</p><h2 id="矩阵编程的基本步骤">矩阵编程的基本步骤<a class="header-anchor" href="#矩阵编程的基本步骤">​</a></h2><p>Cube矩阵计算的基本步骤为：数据搬入 → 数据加载 → 计算 → 数据搬出。当我们描述一个常见的Cube矩阵计算时，需要执行以下四个步骤：</p><ol><li>通过DMA将数据从GM搬入到<code>Local Memory(L1 Buffer)</code></li><li>通过数据加载将L1 Buffer搬入到<code>L0A Buffer &amp; L0B Buffer</code></li><li>进行矩阵计算，计算结果存储在<code>L0C Buffer</code>中</li><li>通过DMA将数据从<code>L0C Buffer</code>搬出到GM</li></ol><h2 id="矩阵计算内存管理">矩阵计算内存管理<a class="header-anchor" href="#矩阵计算内存管理">​</a></h2><h3 id="矩阵计算内存申请">矩阵计算内存申请<a class="header-anchor" href="#矩阵计算内存申请">​</a></h3><p>矩阵计算编程主要通过L0A/L0B/L0C Buffer进行矩阵计算。开发者需将输入数据从Global Memory（以下简称GM）搬入L1 Buffer，再从L1 Buffer搬入L0A/L0B Buffer，最终通过Cube计算指令完成计算。L1 Buffer与L0A/L0B/L0C Buffer均通过LocalTensor对象进行管理，开发者可通过LocalMemAllocator分配器申请矩阵计算所需的内存空间。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__global__</span><span class="w"> </span><span class="n">__cube__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">matmul_custom</span><span class="p">(...)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">m_size</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">128</span><span class="p">;</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">n_size</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">128</span><span class="p">;</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">k_size</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">256</span><span class="p">;</span>

<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalMemAllocator</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">Hardware</span><span class="o">::</span><span class="n">L1</span><span class="o">&gt;</span><span class="w"> </span><span class="n">l1Allocator</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalMemAllocator</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">Hardware</span><span class="o">::</span><span class="n">L0A</span><span class="o">&gt;</span><span class="w"> </span><span class="n">l0aAllocator</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalMemAllocator</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">Hardware</span><span class="o">::</span><span class="n">L0B</span><span class="o">&gt;</span><span class="w"> </span><span class="n">l0bAllocator</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalMemAllocator</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">Hardware</span><span class="o">::</span><span class="n">L0C</span><span class="o">&gt;</span><span class="w"> </span><span class="n">l0cAllocator</span><span class="p">;</span>

<span class="w">    </span><span class="c1">// Allocate L1 Buffer for matrix A and B</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">l1a_buffer</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">l1Allocator</span><span class="p">.</span><span class="n">Alloc</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="n">m_size</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">k_size</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">l1b_buffer</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">l1Allocator</span><span class="p">.</span><span class="n">Alloc</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="n">k_size</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">n_size</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="c1">// Allocate L0A/L0B/L0C Buffer for matrix computation</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">l0a_buffer</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">l0aAllocator</span><span class="p">.</span><span class="n">Alloc</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="n">m_size</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">k_size</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">l0b_buffer</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">l0bAllocator</span><span class="p">.</span><span class="n">Alloc</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="n">k_size</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">n_size</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="w"> </span><span class="n">l0c_buffer</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">l0cAllocator</span><span class="p">.</span><span class="n">Alloc</span><span class="o">&lt;</span><span class="kt">float</span><span class="p">,</span><span class="w"> </span><span class="n">m_size</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">n_size</span><span class="o">&gt;</span><span class="p">();</span>

<span class="w">    </span><span class="c1">// ... Use Buffer for matrix computation</span>
<span class="p">}</span>
</code></pre></div><h3 id="矩阵计算内存布局">矩阵计算内存布局<a class="header-anchor" href="#矩阵计算内存布局">​</a></h3><p>矩阵计算单元采用分块计算逻辑，其中16×16是矩阵计算单元分形的基本粒度（对于half数据类型；int8类型为16×32或32×16；fp32类型分形为16×8），硬件可以并行处理多个矩阵计算单元。在传统的线性存储布局（如行主序或列主序）中，数据按行或列连续存放。当需要读取一个16×16的矩形数据块时，若直接从内存中获取，则需访问不连续的多个内存地址以逐行“收集”数据，这种非连续访问会导致内存效率显著下降。 为解决上述问题，引入了矩阵分形存储格式。该格式通过软件层对数据进行重排，使每个16×16计算块在物理内存中连续存放。硬件仅需发起一次连续读取，即可将整个数据块加载至片上寄存器，避免了多地址寻址开销，从而大幅提升矩阵计算单元的数据吞吐率。对于half数据类型，16×16是矩阵计算单元的基本分形粒度，当前支持Cube计算的产品型号包括<a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>和<a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>。 昇腾AI处理器的矩阵计算单元为追求极高的数据吞吐率与计算密度，采用了专有的硬件架构设计。与通用CPU常用的连续线性存储不同，该单元要求输入输出数据必须符合特定的分形存储格式。在使用Ascend C的Mmad类接口进行算子开发时，深入理解这些数据格式对于实现正确的数据搬运、分块及性能优化至关重要。 为便于理解与记忆，文档采用“大Y小x”的直观命名法：</p><ul><li>大Y（Z/N）：表示分形矩阵之间的排列顺序（Z为行主序，N为列主序）。</li><li>小x（z/n）：表示分形矩阵内部元素的排列顺序（z为行主序，n为列主序）。</li></ul><h3 id="关键分形格式详解">关键分形格式详解<a class="header-anchor" href="#关键分形格式详解">​</a></h3><p>矩阵分形存储格式是对多维Tensor在内存中数据排布格式的描述。 为了适配矩阵计算单元的物理读取路径，不同的产品形态有不同的格式要求： 针对<a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>，矩阵乘法C = A × B要求：左矩阵A使用Zz格式，右矩阵B使用Zn格式，结果矩阵C使用Nz格式，如下图所示：</p><p><img src="`+n+'" alt="矩阵乘法场景涉及的数据格式"></p><p>针对<a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>，矩阵乘法C = A × B要求：左矩阵A使用Nz格式，右矩阵B使用Zn格式，结果矩阵C使用Nz格式，如下图所示：</p><p><img src="'+p+'" alt="矩阵乘法场景涉及的数据格式"></p><h4 id="ND格式（N-Dimension）">ND格式（N-Dimension）<a class="header-anchor" href="#ND格式（N-Dimension）">​</a></h4><p>ND格式是通用的N维张量格式，数据在内存中连续线性存放，通常存在于GM中。在进行矩阵运算前，通常需要将其转换为Nz格式以适配Cube计算单元。</p><h4 id="Nz格式">Nz格式<a class="header-anchor" href="#Nz格式">​</a></h4><p>Nz格式主要用于L1 Buffer和L0C Buffer中存放数据。针对<a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>，L0A Buffer也采用Nz分形格式。该格式采用大N（外部列主序）+ 小z（内部行主序）的方式排布。</p><p><img src="'+a+'" alt="Nz数据排布格式"></p><p>Nz是Ascend架构的中间格式，介于线性数据(ND)和计算专用数据(Zz/Zn)之间，便于格式转换。大N排布（列主序Block）的设计通常是为了配合多核并行或后续算子（如Vector向量计算）在处理通道（Channel）维度数据时的便利性。</p><blockquote><p>📌 Nz格式在不同Buffer中的应用场景：</p><ul><li><strong>L0C Buffer</strong>: 存储矩阵乘法结果。分形形状为16×16（对于half数据类型，256元素），适合Cube计算单元高效运算。</li><li><strong>L1 Buffer</strong>: 存储中间数据。分形形状为16×(32B/sizeof(DataType))，大小512字节，便于转换为Zz和Zn格式。</li><li><strong>L0A Buffer（仅<a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>）</strong>: 存储左矩阵。</li></ul></blockquote><h4 id="Zz格式">Zz格式<a class="header-anchor" href="#Zz格式">​</a></h4><p>针对<a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>，L0A Buffer使用此格式（<a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>使用Nz格式）。该格式采用大Z（外部行主序）+ 小z（内部行主序）。</p><p><img src="'+l+'" alt="Zz格式(以half类型为例)"></p><p>在矩阵乘法中，A矩阵逐行读取数据。Zz格式的行主序特性使同一行元素物理地址连续，与计算访问模式匹配，便于Cube单元左侧通道通过DMA连续读取，避免跨步访问，提升数据搬运效率。</p><h4 id="Zn格式">Zn格式<a class="header-anchor" href="#Zn格式">​</a></h4><p>Zn格式主要用于L0B Buffer中存放数据，如果离线处理好的右矩阵数据直接为Zn格式，则在GM和L1 Buffer上存储该格式。该格式采用大Z(外部行主序) + 小n(内部列主序)。</p><p><img src="'+f+'" alt="Zn格式(以half类型为例)"></p><p>矩阵乘法需读取B矩阵列向量。普通行主序存储导致列数据在内存中地址不连续。Zn格式在分形内部按列存储，使列数据在L0B中紧凑排列，便于Cube单元右侧通道线性读取完整列向量，避免跨步访问。</p><h3 id="格式转换">格式转换<a class="header-anchor" href="#格式转换">​</a></h3><p>根据上述信息，Global Memory采用ND格式，L1 Buffer采用Nz格式，因此需进行ND2NZ格式转换。</p><p><img src="'+c+'" alt="ND2NZ格式转换"></p><p>以上图为例，图中展示了一个具体的M=40、K=56的矩阵（数据类型为half），在从GM搬运至L1 Buffer并转换为Nz格式时的内存排布变化：</p><ul><li>原始数据（ND格式）：左侧GM中存储的是原始矩阵，shape为40×56。数据呈线性连续排布（图中长箭头所示），遵循行主序规则。</li><li>对齐与填充：由于Cube单元的分形要求，目标矩阵必须能够被16×16的Block整除（假设数据类型为half，即32/sizeof(half)=16)。M轴填充：原始M = 40不能被16整除，需向上补齐至48（16×3）。K轴填充：原始K=56不能被16整除，需向上补齐至64（16×4）。图中灰色区域即为补齐产生的无效数据，白色区域为原始有效数据。</li><li>重排布（Nz格式）：右侧L1 Buffer中，数据被重组为3×4个分形块。Z字流动：每个16×16的小方块内部以及方块之间，均按照特定的Z字形顺序存储（如图中折线箭头所示），完成了从“线性”到“分形”的物理映射，做好了进入Cube计算的准备。</li></ul><h2 id="基础Tensor编程范式">基础Tensor编程范式<a class="header-anchor" href="#基础Tensor编程范式">​</a></h2><p>基础Tensor仅封装数据指针与大小信息，开发者需手动配置搬运参数、计算分形步长、管理内存布局。适用于需要精细控制硬件行为的场景。</p><h3 id="矩阵数据搬入">矩阵数据搬入<a class="header-anchor" href="#矩阵数据搬入">​</a></h3><p>矩阵搬入接口实现Global Memory经L1 Buffer到L0A/L0B Buffer的数据传输，通常与Mmad接口配合使用。该接口支持多种搬运模式：二维搬运、三维格式转换、压缩数据解压、矩阵转置、稀疏化数据处理等。</p><p>开发者通过配置参数控制搬运路径、起始位置、长度等信息，充分利用硬件能力，最大化算子性能。每种数据通路对应特定的存储层级和访问特性。</p><p>结合上述数据流和分形知识，C++ Tensor编程提供以下矩阵搬入能力（完整接口见API参考手册）：</p><table><thead><tr><th>数据通路</th><th>功能</th><th>C++ Tensor编程接口</th><th>分形支持情况</th></tr></thead><tbody><tr><td>Global Memory → L1 Buffer</td><td>随路转换ND2NZ搬运</td><td><code>DataCopy(dst, src, nd2nzParams)</code></td><td><img src="'+o+'" alt="ND-&gt;Nz"></td></tr><tr><td>L1 Buffer → L0A Buffer</td><td>将L1 Buffer数据搬运到L0A Buffer中</td><td><code>LoadData(dst, src, l12l0Params)</code></td><td><img src="'+e+'" alt="Nz-&gt;Zz"><br><a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>上L0A分形为Nz，搬运时为Nz-Nz</td></tr><tr><td>L1 Buffer → L0B Buffer</td><td>将L1 Buffer数据搬运到L0B Buffer中</td><td><code>LoadData(dst, src, l12l0Params)</code></td><td><img src="'+t+'" alt="Nz-&gt;Zn"></td></tr></tbody></table><h4 id="GM2L1-随路转换ND2NZ搬运">GM2L1 随路转换ND2NZ搬运<a class="header-anchor" href="#GM2L1-随路转换ND2NZ搬运">​</a></h4><p>该能力主要实现将矩阵从GM搬运至L1 Buffer，并支持在数据搬运时进行ND到Nz格式的转换。</p><p>该能力通过<code>DataCopy</code>接口配合<code>Nd2NzParams</code>参数实现，配置<code>ndNum</code>、<code>srcDValue</code>等参数完成GM2L1搬运和ND2NZ格式转换。</p><p><img src="'+r+`" alt="GM到L1的ND2NZ搬运示例"></p><p>以上图为例，实现A矩阵(Shape(16, 23)，数据类型为half)从GM搬运到L1的能力，针对<a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>，调用接口如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// Allocate L1 Buffer space</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">m</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">16</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">k</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">32</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalMemAllocator</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">Hardware</span><span class="o">::</span><span class="n">L1</span><span class="o">&gt;</span><span class="w"> </span><span class="n">l1Allocator</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">dst</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">l1Allocator</span><span class="p">.</span><span class="n">Alloc</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="n">m</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">k</span><span class="o">&gt;</span><span class="p">();</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">srcGlobal</span><span class="p">;</span>
<span class="n">srcGlobal</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">((</span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="p">)</span><span class="n">src</span><span class="p">);</span>

<span class="c1">// Set parameters for Nd2NzParams</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Nd2NzParams</span><span class="w"> </span><span class="n">intriParams</span><span class="p">{</span><span class="cm">/*ndNum*/</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="cm">/*nValue*/</span><span class="mi">16</span><span class="p">,</span><span class="w"> </span><span class="cm">/*dValue*/</span><span class="mi">23</span><span class="p">,</span><span class="w"> </span><span class="cm">/*srcNdMatrixStride*/</span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="cm">/*srcDValue*/</span><span class="mi">32</span><span class="p">,</span><span class="w"> </span><span class="cm">/*dstNzC0Stride*/</span><span class="mi">16</span><span class="p">,</span><span class="w"> </span><span class="cm">/*dstNzNStride*/</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="cm">/*dstNzMatrixStride*/</span><span class="mi">0</span><span class="p">};</span>

<span class="c1">// Global Memory -&gt; Local Memory with ND2NZ conversion</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">srcGlobal</span><span class="p">,</span><span class="w"> </span><span class="n">intriParams</span><span class="p">);</span>
</code></pre></div><h4 id="L12L0-数据搬运">L12L0 数据搬运<a class="header-anchor" href="#L12L0-数据搬运">​</a></h4><p>该能力主要实现将矩阵从L1 Buffer搬运至L0A/L0B Buffer，并支持从Nz分形转换到Zz或Zn格式。针对<a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>，C++ Tensor编程提供了<code>LoadData</code>接口配合<code>LoadData2DParamsV2</code>参数，以512B数据分形为基本单位完成L1 Buffer到L0A/L0B Buffer的2D搬运，并可通过<code>ifTranspose</code>配置分形转置。对于3D搬运场景，需要使用<code>LoadData</code>接口配合<code>LoadData3DParamsV1</code>或<code>LoadData3DParamsV2</code>参数；其中NPU架构版本3510不支持<code>LoadData3DParamsV1</code>，需使用<code>LoadData3DParamsV2</code>。</p><p><img src="`+i+`" alt="L12L0A非转置搬运"></p><p>通过如下方式调用可完成上述的L1 Buffer到L0A Buffer的搬入操作。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalMemAllocator</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">Hardware</span><span class="o">::</span><span class="n">L1</span><span class="o">&gt;</span><span class="w"> </span><span class="n">l1Allocator</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalMemAllocator</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">Hardware</span><span class="o">::</span><span class="n">L0A</span><span class="o">&gt;</span><span class="w"> </span><span class="n">l0aAllocator</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">l1_buffer</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">l1Allocator</span><span class="p">.</span><span class="n">Alloc</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="mi">6400</span><span class="o">&gt;</span><span class="p">();</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">l0a_buffer</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">l0aAllocator</span><span class="p">.</span><span class="n">Alloc</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="mi">2304</span><span class="o">&gt;</span><span class="p">();</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">LoadData2DParamsV2</span><span class="w"> </span><span class="n">l12l0Params</span><span class="p">;</span>
<span class="c1">// mStep is 2, kStep is 3, indicating transfer of 6 data blocks</span>
<span class="n">l12l0Params</span><span class="p">.</span><span class="n">mStep</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="n">l12l0Params</span><span class="p">.</span><span class="n">kStep</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">3</span><span class="p">;</span>
<span class="c1">// mStartPosition is 2, indicates M direction transfer starting position</span>
<span class="n">l12l0Params</span><span class="p">.</span><span class="n">mStartPosition</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="c1">// kStartPosition is 2, indicates K direction transfer starting position</span>
<span class="n">l12l0Params</span><span class="p">.</span><span class="n">kStartPosition</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="c1">// srcStride is 5, indicates interval between fractal starting addresses in K direction</span>
<span class="n">l12l0Params</span><span class="p">.</span><span class="n">srcStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">5</span><span class="p">;</span>
<span class="c1">// dstStride is 3: indicates interval between fractal starting addresses in M direction</span>
<span class="n">l12l0Params</span><span class="p">.</span><span class="n">dstStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">3</span><span class="p">;</span>
<span class="c1">// Do not transpose the fractal in this example</span>
<span class="n">l12l0Params</span><span class="p">.</span><span class="n">ifTranspose</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">false</span><span class="p">;</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">LoadData</span><span class="p">(</span><span class="n">l0a_buffer</span><span class="p">,</span><span class="w"> </span><span class="n">l1_buffer</span><span class="p">,</span><span class="w"> </span><span class="n">l12l0Params</span><span class="p">);</span>
</code></pre></div><p>搬运到L0B Buffer采用同样的<code>LoadData</code>接口实现，接口参数及实现功能同L12L0A，可参考<a href="../../../../../api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/cube_compute_load.html">矩阵计算的搬入</a>查看更多内容。</p><p>当输入A矩阵（GM）是转置排布（K×M）时，搬入到L1 Buffer后为（K×M）排布的Nz分形。要使L0A Buffer存放（M×K）的矩阵，需要在L1 Buffer到L0A Buffer的搬运过程中进行转置。针对<a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>，可使用<code>LoadDataWithTranspose</code>接口，调用示例如下。</p><p><img src="`+d+`" alt="需要转置的处理场景"></p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// A矩阵LoadDataWithTranspose: Nz -&gt; Zz</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">dstOffset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">CeilDivision</span><span class="p">(</span><span class="n">k</span><span class="p">,</span><span class="w"> </span><span class="n">fractalShape</span><span class="p">[</span><span class="mi">1</span><span class="p">])</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">fractalSize</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">fractalNum</span><span class="p">;</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">srcOffset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">CeilDivision</span><span class="p">(</span><span class="n">k</span><span class="p">,</span><span class="w"> </span><span class="n">fractalShape</span><span class="p">[</span><span class="mi">0</span><span class="p">]</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">fractalNum</span><span class="p">)</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">fractalSize</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">fractalNum</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LoadData2dTransposeParams</span><span class="w"> </span><span class="n">loadDataParams</span><span class="p">;</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">startIndex</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">repeatTimes</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">CeilDivision</span><span class="p">(</span><span class="n">k</span><span class="p">,</span><span class="w"> </span><span class="n">fractalShape</span><span class="p">[</span><span class="mi">0</span><span class="p">]</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">fractalNum</span><span class="p">);</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">srcStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">dstGap</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">dstFracGap</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">CeilDivision</span><span class="p">(</span><span class="n">k</span><span class="p">,</span><span class="w"> </span><span class="n">fractalShape</span><span class="p">[</span><span class="mi">1</span><span class="p">])</span><span class="w"> </span><span class="o">-</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">int</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">CeilDivision</span><span class="p">(</span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">fractalShape</span><span class="p">[</span><span class="mi">1</span><span class="p">]);</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">  </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LoadDataWithTranspose</span><span class="p">(</span><span class="n">l0aTensor</span><span class="p">[</span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">dstOffset</span><span class="p">],</span><span class="w"> </span><span class="n">l1aTensor</span><span class="p">[</span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">srcOffset</span><span class="p">],</span><span class="w"> </span><span class="n">loadDataParams</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div><p>针对<a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>，<code>LoadDataWithTranspose</code>仅支持L1 Buffer到L0B Buffer通路，推荐使用<code>LoadData2dTransposeParamsV2</code>作为搬运参数，不支持本节所述的L1 Buffer到L0A Buffer转置场景。该场景需要改用<code>LoadData</code>接口配合<code>LoadData2DParamsV2</code>参数，并将<code>ifTranspose</code>设置为<code>true</code>。</p><p>以<code>half</code>数据类型为例，A矩阵在L1 Buffer上为（K×M）的Nz分形，在L0A Buffer上需要转换为（M×K）的Nz分形，可按如下方式配置：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">fractalShape</span><span class="p">[</span><span class="mi">2</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">{</span><span class="mi">16</span><span class="p">,</span><span class="w"> </span><span class="mi">32</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">)};</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">kAlignL1</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">CeilAlign</span><span class="p">(</span><span class="n">k</span><span class="p">,</span><span class="w"> </span><span class="n">fractalShape</span><span class="p">[</span><span class="mi">0</span><span class="p">]);</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">mAlignL1</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">CeilAlign</span><span class="p">(</span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">fractalShape</span><span class="p">[</span><span class="mi">1</span><span class="p">]);</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">mAlignL0</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">CeilAlign</span><span class="p">(</span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">fractalShape</span><span class="p">[</span><span class="mi">0</span><span class="p">]);</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">LoadData2DParamsV2</span><span class="w"> </span><span class="n">loadDataParams</span><span class="p">;</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">mStartPosition</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">kStartPosition</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">mStep</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">CeilDivision</span><span class="p">(</span><span class="n">kAlignL1</span><span class="p">,</span><span class="w"> </span><span class="n">fractalShape</span><span class="p">[</span><span class="mi">0</span><span class="p">]);</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">kStep</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">CeilDivision</span><span class="p">(</span><span class="n">mAlignL1</span><span class="p">,</span><span class="w"> </span><span class="n">fractalShape</span><span class="p">[</span><span class="mi">1</span><span class="p">]);</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">srcStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">CeilDivision</span><span class="p">(</span><span class="n">kAlignL1</span><span class="p">,</span><span class="w"> </span><span class="n">fractalShape</span><span class="p">[</span><span class="mi">0</span><span class="p">]);</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">dstStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">CeilDivision</span><span class="p">(</span><span class="n">mAlignL0</span><span class="p">,</span><span class="w"> </span><span class="n">fractalShape</span><span class="p">[</span><span class="mi">0</span><span class="p">]);</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">ifTranspose</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">true</span><span class="p">;</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">sid</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LoadData</span><span class="p">(</span><span class="n">l0aTensor</span><span class="p">,</span><span class="w"> </span><span class="n">l1aTensor</span><span class="p">,</span><span class="w"> </span><span class="n">loadDataParams</span><span class="p">);</span>
</code></pre></div><h3 id="矩阵数据搬出">矩阵数据搬出<a class="header-anchor" href="#矩阵数据搬出">​</a></h3><p>矩阵搬出接口实现L0C Buffer到Global Memory或L1 Buffer的数据传输，支持随路量化、ReLU、NZ2ND格式转换、通道拆分合并等操作。开发者通过配置参数控制搬运路径、位置和长度等，通常在<code>Mmad</code>接口后使用。针对<a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>，还支持L0C Buffer到Unified Buffer（UB）的搬运以及UB双目标模式。L0C Buffer到Global Memory通路的NZ2ND格式转换同时支持NPU架构版本2201和3510。矩阵搬出能力如下图所示：</p><p><a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>下的矩阵搬出流程为：</p><p><img src="`+m+'" alt="矩阵搬出流程"></p><p><a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>下的矩阵搬出流程为：</p><p><img src="'+w+'" alt="矩阵搬出流程"></p><p>矩阵搬出接口支持多种随路能力的灵活组合，以L0C Buffer到Global Memory的搬运场景为例：矩阵计算结果暂存于L0C Buffer后需搬运至GM，在此过程中可协同执行随路量化、ReLU激活、格式转换及通道拆分合并等操作。下图分别展示了不同NPU架构版本下这些随路能力的有效组合、中间数据类型及完整数据路径。例如，L0C Buffer中的F32数据可通过QF322B8_PRE随路量化得到B8数据，可选使能ReLU后经NZ2NZ/NZ2ND格式转换输出至GM。图中F32-&gt;F16和F32-&gt;BF16为数据类型转换，其余路径为随路Scalar/Vector量化模式。</p><p><a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>下的矩阵搬出能力为：</p><p><img src="'+h+'" alt="L0C2GM搬运"></p><p><a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>下的矩阵搬出能力为：</p><p><img src="'+u+`" alt="L0C2GM搬运"></p><p>C++ Tensor编程提供了<code>DataCopy</code>接口配合<code>DataCopyCO12DstParams</code>参数来使能发挥芯片的各种随路能力，通过直接传入配置参数可完成随路搬运的操作。 示例：Mmad含有矩阵乘偏置，左矩阵和右矩阵的数据类型为int8_t，结果矩阵的数据类型为int32_t。量化模式为DEQF16，Scalar量化参数为2.0，将Mmad计算出的结果由int32_t量化成half并搬出。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// Scalar quantization, quantization parameter is 2.0</span>
<span class="kt">float</span><span class="w"> </span><span class="n">quantScalar</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mf">2.0f</span><span class="p">;</span>
<span class="kt">uint64_t</span><span class="w"> </span><span class="n">deqScalar</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">uint64_t</span><span class="o">&gt;</span><span class="p">(</span><span class="o">*</span><span class="k">reinterpret_cast</span><span class="o">&lt;</span><span class="kt">int32_t</span><span class="o">*&gt;</span><span class="p">(</span><span class="o">&amp;</span><span class="n">quantScalar</span><span class="p">));</span>
<span class="c1">// Write scalar quantization parameter to register for subsequent DataCopy instructions</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetFixpipePreQuantFlag</span><span class="p">(</span><span class="n">deqScalar</span><span class="p">);</span>
<span class="c1">// Create parameters for DataCopy</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopyCO12DstParams</span><span class="w"> </span><span class="n">intriParams</span><span class="p">;</span>
<span class="n">intriParams</span><span class="p">.</span><span class="n">nSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">n</span><span class="p">;</span>
<span class="n">intriParams</span><span class="p">.</span><span class="n">mSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">m</span><span class="p">;</span>
<span class="n">intriParams</span><span class="p">.</span><span class="n">srcStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">CeilAlign</span><span class="p">(</span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">CUBE_BLOCK</span><span class="p">);</span>
<span class="n">intriParams</span><span class="p">.</span><span class="n">dstStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">n</span><span class="p">;</span>
<span class="n">intriParams</span><span class="p">.</span><span class="n">quantPre</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">QuantMode_t</span><span class="o">::</span><span class="n">DEQF16</span><span class="p">;</span>
<span class="n">intriParams</span><span class="p">.</span><span class="n">reluPre</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span><span class="w"> </span><span class="c1">// Enable ReLU</span>
<span class="n">intriParams</span><span class="p">.</span><span class="n">nz2ndEn</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">true</span><span class="p">;</span><span class="w"> </span><span class="c1">// Enable NZ2ND format conversion</span>
<span class="c1">// Set NZ2ND parameters before enabling NZ2ND in DataCopy</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetFixpipeNz2ndFlag</span><span class="p">(</span><span class="cm">/*ndNum*/</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="cm">/*srcNdStride*/</span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="cm">/*dstNdStride*/</span><span class="mi">1</span><span class="p">);</span>
<span class="c1">// Execute data transfer based on configurations in intriParams</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">cGM</span><span class="p">,</span><span class="w"> </span><span class="n">cLocal</span><span class="p">,</span><span class="w"> </span><span class="n">intriParams</span><span class="p">);</span>
</code></pre></div><p>另外，开发者可通过<code>SetFixPipeConfig</code>设置Tensor量化参数或清除unitFlag，通过<code>SetFixpipeNz2ndFlag</code>设置NZ2ND格式转换信息。<code>SetFixPipeConfig</code>的<code>reluPreTensor</code>和<code>quantPreTensor</code>需要为Fixpipe Buffer上数据类型为<code>uint64_t</code>的<code>LocalTensor</code>，当前<code>reluPreTensor</code>传入空<code>LocalTensor</code>即可。对应的接口和处理能力如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// Set vector quantization parameters for on-the-fly quantization during data transfer</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetFixPipeConfig</span><span class="p">(</span><span class="n">reluPreTensor</span><span class="p">,</span><span class="w"> </span><span class="n">quantPreTensor</span><span class="p">,</span><span class="w"> </span><span class="n">isUnitFlag</span><span class="p">);</span>

<span class="c1">// Configure parameters for NZ to ND format conversion during data transfer</span>
<span class="c1">// Number of ND matrices</span>
<span class="kt">uint16_t</span><span class="w"> </span><span class="n">ndNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="c1">// Source stride in fractal unit, offset between adjacent source NZ matrix headers</span>
<span class="kt">uint16_t</span><span class="w"> </span><span class="n">srcNdStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="c1">// Destination stride, offset between adjacent destination ND matrix headers</span>
<span class="kt">uint16_t</span><span class="w"> </span><span class="n">dstNdStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetFixpipeNz2ndFlag</span><span class="p">(</span><span class="n">ndNum</span><span class="p">,</span><span class="w"> </span><span class="n">srcNdStride</span><span class="p">,</span><span class="w"> </span><span class="n">dstNdStride</span><span class="p">);</span>

<span class="c1">// Set scalar quantization parameter for on-the-fly quantization in DataCopy (L0C-&gt;GM, L0C-&gt;L1)</span>
<span class="kt">float</span><span class="w"> </span><span class="n">tmp</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mf">0.5f</span><span class="p">;</span>
<span class="c1">// Convert float value tmp to uint64_t deqScalar</span>
<span class="kt">uint64_t</span><span class="w"> </span><span class="n">deqScalar</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">uint64_t</span><span class="o">&gt;</span><span class="p">(</span><span class="o">*</span><span class="k">reinterpret_cast</span><span class="o">&lt;</span><span class="kt">int32_t</span><span class="o">*&gt;</span><span class="p">(</span><span class="o">&amp;</span><span class="n">tmp</span><span class="p">));</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetFixpipePreQuantFlag</span><span class="p">(</span><span class="n">deqScalar</span><span class="p">);</span>
</code></pre></div><p>详细说明可参考接口说明文档<a href="../../../../../api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI.html">Cube接口说明</a>。</p><h3 id="矩阵计算">矩阵计算<a class="header-anchor" href="#矩阵计算">​</a></h3><p><a href="../../../../../api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute/Mmad.html">Mmad</a>是Ascend C封装NPU硬件计算能力的矩阵乘加核心接口，用于全连接层、卷积层等算子开发，实现C = A × B + C的矩阵乘加计算（输入为L0A Buffer和L0B Buffer，输出为L0C Buffer），其中针对<a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>，L0A Buffer分形为Zz、L0B Buffer分形为Zn、L0C Buffer分形为Nz，而<a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>产品L0A Buffer分形为Nz。</p><p><img src="`+_+`" alt="NPU架构版本3510 Mmad计算"></p><p><strong>表 矩阵乘计算A、B、C矩阵说明（<a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>）</strong></p><table><thead><tr><th>矩阵</th><th>存储位置</th><th>维度</th><th>数据格式</th><th>数据类型</th></tr></thead><tbody><tr><td>A</td><td>L0A Buffer</td><td>M × K</td><td>Nz</td><td>half</td></tr><tr><td>B</td><td>L0B Buffer</td><td>K × N</td><td>Zn</td><td>half</td></tr><tr><td>C</td><td>L0C Buffer</td><td>M × N（支持Bias初始化，维度1×N）</td><td>Nz</td><td>float</td></tr></tbody></table><p>C++ Tensor编程提供了一系列<code>Mmad</code>重载接口，支持不同数据类型的矩阵计算。以下代码实现上图中的矩阵乘计算。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// Define L0A/L0B matrix sizes</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">mSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">64</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">kSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">64</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">nSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">64</span><span class="p">;</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalMemAllocator</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">Hardware</span><span class="o">::</span><span class="n">L0A</span><span class="o">&gt;</span><span class="w"> </span><span class="n">l0aAllocator</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalMemAllocator</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">Hardware</span><span class="o">::</span><span class="n">L0B</span><span class="o">&gt;</span><span class="w"> </span><span class="n">l0bAllocator</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalMemAllocator</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">Hardware</span><span class="o">::</span><span class="n">L0C</span><span class="o">&gt;</span><span class="w"> </span><span class="n">l0cAllocator</span><span class="p">;</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">a_matrix</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">l0aAllocator</span><span class="p">.</span><span class="n">Alloc</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="n">mSize</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">kSize</span><span class="o">&gt;</span><span class="p">();</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">b_matrix</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">l0bAllocator</span><span class="p">.</span><span class="n">Alloc</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="n">kSize</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">nSize</span><span class="o">&gt;</span><span class="p">();</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="w"> </span><span class="n">c_matrix</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">l0cAllocator</span><span class="p">.</span><span class="n">Alloc</span><span class="o">&lt;</span><span class="kt">float</span><span class="p">,</span><span class="w"> </span><span class="n">mSize</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">nSize</span><span class="o">&gt;</span><span class="p">();</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">MmadParams</span><span class="w"> </span><span class="n">mmadParams</span><span class="p">;</span>
<span class="c1">// Configure Mmad parameters</span>
<span class="c1">// m direction: 3 fractals, actual value = 3 × 16 = 48</span>
<span class="n">mmadParams</span><span class="p">.</span><span class="n">m</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">48</span><span class="p">;</span>
<span class="c1">// n direction: 3 fractals, actual value = 3 × 16 = 48</span>
<span class="n">mmadParams</span><span class="p">.</span><span class="n">n</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">48</span><span class="p">;</span>
<span class="c1">// k direction: 4 fractals, actual value = 4 × 16 = 64</span>
<span class="n">mmadParams</span><span class="p">.</span><span class="n">k</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">64</span><span class="p">;</span>

<span class="c1">// Feature parameters</span>
<span class="c1">// unitFlag: Controls fine-grained parallelism of Mmad and Fixpipe instructions</span>
<span class="n">mmadParams</span><span class="p">.</span><span class="n">unitFlag</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="c1">// disableGemv: Configures whether to enable GEMV mode when M=1</span>
<span class="n">mmadParams</span><span class="p">.</span><span class="n">disableGemv</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">false</span><span class="p">;</span>
<span class="c1">// cmatrixInitVal: Initializes C matrix to zero before computation</span>
<span class="n">mmadParams</span><span class="p">.</span><span class="n">cmatrixInitVal</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">true</span><span class="p">;</span>
<span class="c1">// cmatrixSource: Does not initialize C matrix from BiasTable Buffer</span>
<span class="n">mmadParams</span><span class="p">.</span><span class="n">cmatrixSource</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">false</span><span class="p">;</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">Mmad</span><span class="p">(</span><span class="n">c_matrix</span><span class="p">,</span><span class="w"> </span><span class="n">a_matrix</span><span class="p">,</span><span class="w"> </span><span class="n">b_matrix</span><span class="p">,</span><span class="w"> </span><span class="n">mmadParams</span><span class="p">);</span>
</code></pre></div><h3 id="同步机制">同步机制<a class="header-anchor" href="#同步机制">​</a></h3><p>AI Core内部执行单元（如MTE2搬运单元、Vector计算单元等）以异步并行方式运行，读写同一存储资源时可能存在数据依赖关系。因此，Cube计算需通过流水同步接口确保正确执行。Cube矩阵计算主要包含四步：数据搬入（Global Memory → L1 Buffer）、数据加载（L1 Buffer → L0A/B Buffer）、矩阵计算（L0A/B Buffer → L0C Buffer）、数据搬出（L0C Buffer → Global Memory）。四个步骤分别对应PIPE_MTE2、PIPE_MTE1、PIPE_M、PIPE_FIX流水线，需通过核内同步接口协调执行顺序，确保各步骤按序完成。</p><p>当开发者进行一个矩阵乘法计算时（<a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>产品），可通过<code>Mutex::Lock</code>&amp;<code>Mutex::Unlock</code>的方式完成对这四个步骤的同步。<a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>产品可使用<code>SetFlag</code>&amp;<code>WaitFlag</code>实现相同同步效果，详见<a href="../cpp_tensor_programming/cpp_tensor_programming_overview.html#%E5%90%8C%E6%AD%A5%E6%9C%BA%E5%88%B6">同步机制</a>。</p><p>以下示例中，核函数（Kernel）入参<code>x</code>、<code>y</code>、<code>z</code>的指针类型与对应<code>GlobalTensor</code>的模板类型一致，因此调用<code>SetGlobalBuffer</code>时可省略显式类型转换。若实参指针类型与<code>GlobalTensor</code>的模板类型不一致，需要先将其显式转换为对应的<code>__gm__ PrimType*</code>类型。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__global__</span><span class="w"> </span><span class="n">__cube__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">matmul_kernel</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">z</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">mutex_id</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="w">    </span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalMemAllocator</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">Hardware</span><span class="o">::</span><span class="n">L1</span><span class="o">&gt;</span><span class="w"> </span><span class="n">l1Allocator</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalMemAllocator</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">Hardware</span><span class="o">::</span><span class="n">L0A</span><span class="o">&gt;</span><span class="w"> </span><span class="n">l0aAllocator</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalMemAllocator</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">Hardware</span><span class="o">::</span><span class="n">L0B</span><span class="o">&gt;</span><span class="w"> </span><span class="n">l0bAllocator</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalMemAllocator</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">Hardware</span><span class="o">::</span><span class="n">L0C</span><span class="o">&gt;</span><span class="w"> </span><span class="n">l0cAllocator</span><span class="p">;</span>
<span class="w">    </span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">al1ATensor</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">l1Allocator</span><span class="p">.</span><span class="n">Alloc</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="n">BLOCK_M</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">BLOCK_K</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">bl1BTensor</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">l1Allocator</span><span class="p">.</span><span class="n">Alloc</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="n">BLOCK_K</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">BLOCK_N</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">l0aTensor</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">l0aAllocator</span><span class="p">.</span><span class="n">Alloc</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="n">BLOCK_M</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">BLOCK_K</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">l0bTensor</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">l0bAllocator</span><span class="p">.</span><span class="n">Alloc</span><span class="o">&lt;</span><span class="n">half</span><span class="p">,</span><span class="w"> </span><span class="n">BLOCK_K</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">BLOCK_N</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="w"> </span><span class="n">l0cTensor</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">l0cAllocator</span><span class="p">.</span><span class="n">Alloc</span><span class="o">&lt;</span><span class="kt">float</span><span class="p">,</span><span class="w"> </span><span class="n">BLOCK_M</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">BLOCK_N</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">aGm</span><span class="p">,</span><span class="w"> </span><span class="n">bGm</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="w"> </span><span class="n">cGm</span><span class="p">;</span>
<span class="w">    </span><span class="n">aGm</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">(</span><span class="n">x</span><span class="p">);</span>
<span class="w">    </span><span class="n">bGm</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">(</span><span class="n">y</span><span class="p">);</span>
<span class="w">    </span><span class="n">cGm</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">(</span><span class="n">z</span><span class="p">);</span>
<span class="w">    </span>
<span class="w">    </span><span class="c1">// Step 1: Data transfer in (Global Memory → L1 Buffer), pipeline is PIPE_MTE2</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Lock</span><span class="o">&lt;</span><span class="n">PIPE_MTE2</span><span class="o">&gt;</span><span class="p">(</span><span class="n">mutex_id</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Nd2NzParams</span><span class="w"> </span><span class="n">nd2nzParamsA</span><span class="p">{</span>
<span class="w">        </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="n">BLOCK_M</span><span class="p">,</span><span class="w"> </span><span class="n">BLOCK_K</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">BLOCK_K</span><span class="p">,</span><span class="w"> </span><span class="p">(</span><span class="n">BLOCK_M</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="mi">15</span><span class="p">)</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="mi">16</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">};</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">al1ATensor</span><span class="p">,</span><span class="w"> </span><span class="n">aGm</span><span class="p">,</span><span class="w"> </span><span class="n">nd2nzParamsA</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Nd2NzParams</span><span class="w"> </span><span class="n">nd2nzParamsB</span><span class="p">{</span>
<span class="w">        </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="n">BLOCK_K</span><span class="p">,</span><span class="w"> </span><span class="n">BLOCK_N</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">BLOCK_N</span><span class="p">,</span><span class="w"> </span><span class="p">(</span><span class="n">BLOCK_K</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="mi">15</span><span class="p">)</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="mi">16</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">};</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">bl1BTensor</span><span class="p">,</span><span class="w"> </span><span class="n">bGm</span><span class="p">,</span><span class="w"> </span><span class="n">nd2nzParamsB</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Unlock</span><span class="o">&lt;</span><span class="n">PIPE_MTE2</span><span class="o">&gt;</span><span class="p">(</span><span class="n">mutex_id</span><span class="p">);</span>
<span class="w">    </span>
<span class="w">    </span><span class="c1">// Step 2: Data transfer in (L1 Buffer → L0A/B Buffer), pipeline is PIPE_MTE1</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Lock</span><span class="o">&lt;</span><span class="n">PIPE_MTE1</span><span class="o">&gt;</span><span class="p">(</span><span class="n">mutex_id</span><span class="p">);</span>
<span class="w">    </span><span class="p">...</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LoadData</span><span class="p">(</span><span class="n">l0aTensor</span><span class="p">,</span><span class="w"> </span><span class="n">al1ATensor</span><span class="p">,</span><span class="w"> </span><span class="n">loadParams</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LoadData</span><span class="p">(</span><span class="n">l0bTensor</span><span class="p">,</span><span class="w"> </span><span class="n">bl1BTensor</span><span class="p">,</span><span class="w"> </span><span class="n">loadParams</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Unlock</span><span class="o">&lt;</span><span class="n">PIPE_MTE1</span><span class="o">&gt;</span><span class="p">(</span><span class="n">mutex_id</span><span class="p">);</span>
<span class="w">    </span>
<span class="w">    </span><span class="c1">// Step 3: Matrix computation (L0A/B Buffer → L0C Buffer), pipeline is PIPE_M</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Lock</span><span class="o">&lt;</span><span class="n">PIPE_M</span><span class="o">&gt;</span><span class="p">(</span><span class="n">mutex_id</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">MmadParams</span><span class="w"> </span><span class="n">mmadParams</span><span class="p">;</span>
<span class="w">    </span><span class="n">mmadParams</span><span class="p">.</span><span class="n">m</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">BLOCK_M</span><span class="p">;</span>
<span class="w">    </span><span class="n">mmadParams</span><span class="p">.</span><span class="n">n</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">BLOCK_N</span><span class="p">;</span>
<span class="w">    </span><span class="n">mmadParams</span><span class="p">.</span><span class="n">k</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">BLOCK_K</span><span class="p">;</span>
<span class="w">    </span><span class="n">mmadParams</span><span class="p">.</span><span class="n">unitFlag</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="w">    </span><span class="n">mmadParams</span><span class="p">.</span><span class="n">cmatrixSource</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">false</span><span class="p">;</span>
<span class="w">    </span><span class="n">mmadParams</span><span class="p">.</span><span class="n">cmatrixInitVal</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">true</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mmad</span><span class="p">(</span><span class="n">l0cTensor</span><span class="p">,</span><span class="w"> </span><span class="n">l0aTensor</span><span class="p">,</span><span class="w"> </span><span class="n">l0bTensor</span><span class="p">,</span><span class="w"> </span><span class="n">mmadParams</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Unlock</span><span class="o">&lt;</span><span class="n">PIPE_M</span><span class="o">&gt;</span><span class="p">(</span><span class="n">mutex_id</span><span class="p">);</span>
<span class="w">    </span>
<span class="w">    </span><span class="c1">// Step 4: Data transfer out (L0C Buffer → Global Memory), pipeline is PIPE_FIX</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Lock</span><span class="o">&lt;</span><span class="n">PIPE_FIX</span><span class="o">&gt;</span><span class="p">(</span><span class="n">mutex_id</span><span class="p">);</span>
<span class="w">    </span><span class="p">...</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">cGm</span><span class="p">,</span><span class="w"> </span><span class="n">l0cTensor</span><span class="p">,</span><span class="w"> </span><span class="n">l0c2gmParams</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Unlock</span><span class="o">&lt;</span><span class="n">PIPE_FIX</span><span class="o">&gt;</span><span class="p">(</span><span class="n">mutex_id</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div><h3 id="基于基础Tensor的矩阵计算编程示例">基于基础Tensor的矩阵计算编程示例<a class="header-anchor" href="#基于基础Tensor的矩阵计算编程示例">​</a></h3><p>结合上述矩阵计算的搬运与计算能力，开发者可基于C++ Tensor编程实现矩阵类算子。具体开发实践可参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/00_introduction/02_matrix/matmul_basic_api/README.md">matmul实现样例</a>。</p><h2 id="扩展Tensor编程范式">扩展Tensor编程范式<a class="header-anchor" href="#扩展Tensor编程范式">​</a></h2><p><a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>在Tensor基础上引入Layout布局概念，将Shape和Stride移到编译期确定，实现类型安全和分形布局自动生成。开发者只需定义Tensor的Layout，搬运和计算接口自动推断底层参数，大幅降低矩阵算子开发难度。</p><blockquote><p>📌 扩展Tensor（带有Layout）能力从<a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>开始支持。</p></blockquote><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>本节扩展Tensor示例使用Tensor API接口。对于本节使用的Nz布局，<code>asc::te::make_frame_layout</code>的类型模板参数可按需省略；示例显式传入<code>half</code>，用于确保Layout的类型和C0推导与Tensor数据类型一致，并非接口新增了强制参数。在使用<code>asc::te::make_tensor</code>封装原始指针、以及调用搬运接口时，需遵循如下规范：原始内存指针必须经由<code>asc::te::make_mem_ptr</code>做封装处理，禁止直接传入裸指针调用<code>make_tensor</code>；执行数据搬运时，应先通过<code>asc::te::make_copy</code>构造与搬运通路相匹配的<code>copy_atom</code>对象，再以<code>asc::te::copy(atom, dst, src)</code>的形式完成搬运。</p></div><h3 id="Layout的层次化表述">Layout的层次化表述<a class="header-anchor" href="#Layout的层次化表述">​</a></h3><p>我们使用Shape和Stride来表达Layout排布格式，Shape用于表达Layout形状，Stride则用于区分不同的排布。比如下图中的行优先和列优先排布：</p><ul><li>行优先:Shape (2, 4) Stride (4, 1)</li><li>列优先:Shape (2, 4) Stride (1, 2)</li></ul><p>图中每个方格中的数字表示该位置元素在内存中按顺序排列时的下标。对于相同的矩阵位置，排布方式不同时，其在内存中的顺序可能是不同的，例如，矩阵坐标 (1, 0) 在行优先和列优先的情况下，对应元素在内存中的顺序分别是4和1。</p><p><img src="`+g+'" alt="行优先排布"></p><p><img src="'+C+'" alt="列优先排布"></p><p>通常Shape或者Stride中的元素是一个单独的正整数（如上文的示例），但是遇到一些复杂的内存排布情况可能无法表达，所以采用层次化表述法，该方式中，元素也可以是一个元组。元组的第一个元素用于描述不同层次中矩阵的行数，元组的第二个元素用于描述不同层次中矩阵的列数。 例如在下图中，Layout的Shape和Stride分别为：</p><ul><li>Shape((2, 3), (2, 4))</li><li>Stride((1, 4), (2, 12))</li></ul><p><img src="'+k+`" alt="层次化Layout表达"></p><p>图中展示了两层矩阵：内层矩阵为内部用灰色线包裹的矩阵，外层矩阵为将内层矩阵视为一个元素时黑色线包裹的矩阵。Shape的第一个元素描述行方向的形状，(2, 3)表示内层矩阵和外层矩阵的行数分别为2和3；Shape的第二个元素描述列方向的形状，(2, 4)表示内层矩阵和外层矩阵的列数分别为2和4。Stride中的每个元素与Shape中的元素对应，表示该对应维度下，相邻元素首地址在内存地址上的间隔，图片中用箭头表示了每个维度相邻元素的首地址间隔。</p><h3 id="矩阵计算中的分形表达">矩阵计算中的分形表达<a class="header-anchor" href="#矩阵计算中的分形表达">​</a></h3><p>在基于Ascend C进行矩阵编程场景下，会用到以下几种常用的Layout，这些格式都采用如上文介绍的层次化表述法来表达，要求有内外层两层矩阵。其中行排布可以看作Z字形排布，列排布可以看作N字形排布，Layout的分形名称从前到后依次描述从外层到内层的排布顺序，比如NZLayout格式表示外层为N字形排布，内层为Z字形排布。四维Layout的具体表达方式如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">Layout</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">((</span><span class="n">Shape</span><span class="p">)</span><span class="o">:</span><span class="w"> </span><span class="p">(</span><span class="n">Stride</span><span class="p">))</span>
<span class="n">Shape</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">((</span><span class="n">ShapeRow0</span><span class="p">,</span><span class="w"> </span><span class="n">ShapeRow1</span><span class="p">),</span><span class="w"> </span><span class="p">(</span><span class="n">ShapeColumn0</span><span class="p">,</span><span class="w"> </span><span class="n">ShapeColumn1</span><span class="p">))</span>
<span class="n">Stride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">((</span><span class="n">StrideRow0</span><span class="p">,</span><span class="w"> </span><span class="n">StrideRow1</span><span class="p">),</span><span class="w"> </span><span class="p">(</span><span class="n">StrideColumn0</span><span class="p">,</span><span class="w"> </span><span class="n">StrideColumn1</span><span class="p">))</span>
</code></pre></div><p>以Nz分形为例，Nz分形格式的内层分形Shape中，ShapeRow0固定为16行，ShapeColumn0固定为32Byte / sizeof(T)，内层分形的Stride中，StrideRow0固定为32Byte / sizeof(T)，StrideColumn0也固定为1，即内层分形按z字形组织，外层分形按N字形组织。ShapeRow1需满足row方向16对齐，ShapeColumn1需满足column方向32B对齐。</p><p><img src="`+a+`" alt="Nz数据排布格式"></p><p>下面是一个连续的Nz Layout示例，其中C0_ELEMENT = Std::Int&lt;32&gt;{} / sizeof(T)。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">Layout</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">((</span><span class="n">Shape</span><span class="p">)</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="p">(</span><span class="n">Stride</span><span class="p">))</span>
<span class="n">Shape</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">((</span><span class="n">Std</span><span class="o">::</span><span class="n">Int</span><span class="o">&lt;</span><span class="mi">16</span><span class="o">&gt;</span><span class="p">{},</span><span class="w"> </span><span class="n">ceil_div</span><span class="p">(</span><span class="n">row</span><span class="p">,</span><span class="w"> </span><span class="n">Std</span><span class="o">::</span><span class="n">Int</span><span class="o">&lt;</span><span class="mi">16</span><span class="o">&gt;</span><span class="p">{})),</span><span class="w"> </span><span class="p">(</span><span class="n">C0_ELEMENT</span><span class="p">,</span><span class="w"> </span><span class="n">ceil_div</span><span class="p">(</span><span class="n">column</span><span class="p">,</span><span class="w"> </span><span class="n">C0_ELEMENT</span><span class="p">)))</span>
<span class="n">Stride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">((</span><span class="n">C0_ELEMENT</span><span class="p">,</span><span class="w"> </span><span class="n">C0_ELEMENT</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">Std</span><span class="o">::</span><span class="n">Int</span><span class="o">&lt;</span><span class="mi">16</span><span class="o">&gt;</span><span class="p">{}),</span><span class="w"> </span><span class="p">(</span><span class="n">Std</span><span class="o">::</span><span class="n">Int</span><span class="o">&lt;</span><span class="mi">1</span><span class="o">&gt;</span><span class="p">{},</span><span class="w"> </span><span class="n">C0_ELEMENT</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">ceil_align</span><span class="p">(</span><span class="n">row</span><span class="p">,</span><span class="w"> </span><span class="n">Std</span><span class="o">::</span><span class="n">Int</span><span class="o">&lt;</span><span class="mi">16</span><span class="o">&gt;</span><span class="p">{})))</span>
</code></pre></div><h3 id="Layout的构造">Layout的构造<a class="header-anchor" href="#Layout的构造">​</a></h3><p>结合如上分形表达的描述，基于Layout的能力，C++ Tensor编程提供了原始的Layout构造接口。例如，需要创建一个形状为（128，256，128）的多维内存排布时，可通过<code>make_layout</code>接口直接构造。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">auto</span><span class="w"> </span><span class="n">three_dim_layout</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_layout</span><span class="p">(</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_shape</span><span class="p">(</span><span class="mi">128</span><span class="p">,</span><span class="w"> </span><span class="mi">256</span><span class="p">,</span><span class="w"> </span><span class="mi">128</span><span class="p">));</span>
</code></pre></div><p>对于一个Nz分形的排布，也可以通过<code>make_layout</code>构造层次化的Layout表达。例如，对于外层大小为（128，256），数据类型为<code>half</code>的Nz数据，可以通过<code>make_layout</code>构造四维Layout排布：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// Define Nz fractal with shape (128, 256), its 4D representation is: ((16, 128 / 16), (16, 256 / 16))</span>
<span class="k">auto</span><span class="w"> </span><span class="n">nz_layout</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_layout</span><span class="p">(</span>
<span class="w">    </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_shape</span><span class="p">(</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_shape</span><span class="p">(</span><span class="mi">16</span><span class="p">,</span><span class="w"> </span><span class="mi">8</span><span class="p">),</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_shape</span><span class="p">(</span><span class="mi">16</span><span class="p">,</span><span class="w"> </span><span class="mi">16</span><span class="p">)));</span>
</code></pre></div><p>Cube矩阵计算中对于不同的内部存储都有着自己独特的分形结构，为了简化用户的编写，C++ Tensor编程提供了<code>make_frame_layout</code>来简化用户编写生成如上的四维Layout定义：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// Use make_frame_layout to simplify Nz fractal definition, user only needs to perceive the fractal structure of corresponding storage, no need to directly express 4D structure</span>
<span class="k">auto</span><span class="w"> </span><span class="n">nz_layout</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_frame_layout</span><span class="o">&lt;</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">nz_layout_ptn</span><span class="p">,</span><span class="w"> </span><span class="n">half</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">128</span><span class="p">,</span><span class="w"> </span><span class="mi">256</span><span class="p">);</span>
</code></pre></div><h3 id="基于Layout的Tensor表达">基于Layout的Tensor表达<a class="header-anchor" href="#基于Layout的Tensor表达">​</a></h3><p>扩展的Tensor是将上述Layout信息内置到Tensor结构中，由数据指针和数据布局组成。一个Tensor对象同时描述“数据放在哪里”和“数据长什么样”。 C++ Tensor提供了<code>make_tensor</code>函数，用于构造带有Layout的扩展Tensor结构。例如，定义一个形状为（128，256）、数据类型为<code>half</code>的Global Memory数据块，以及一个同等大小的L1 Buffer数据块（Nz分形布局），可表达为：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// Construct Layout for Global Memory &amp; L1 Buffer </span>
<span class="k">auto</span><span class="w"> </span><span class="n">global_layout</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_layout</span><span class="p">(</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_shape</span><span class="p">(</span><span class="mi">128</span><span class="p">,</span><span class="w"> </span><span class="mi">256</span><span class="p">));</span>
<span class="k">auto</span><span class="w"> </span><span class="n">l1_layout</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_frame_layout</span><span class="o">&lt;</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">nz_layout_ptn</span><span class="p">,</span><span class="w"> </span><span class="n">half</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">128</span><span class="p">,</span><span class="w"> </span><span class="mi">256</span><span class="p">);</span>

<span class="c1">// Construct global_tensor &amp; local_tensor through memory pointer + Layout</span>
<span class="k">auto</span><span class="w"> </span><span class="n">global_tensor</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_tensor</span><span class="p">(</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">gm_ptr</span><span class="p">),</span><span class="w"> </span><span class="n">global_layout</span><span class="p">);</span>
<span class="k">auto</span><span class="w"> </span><span class="n">l1_tensor</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_tensor</span><span class="p">(</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">l1_ptr</span><span class="p">),</span><span class="w"> </span><span class="n">l1_layout</span><span class="p">);</span>
</code></pre></div><p>扩展Tensor提供了<code>operator[]</code>元素访问、<code>operator()</code>子Tensor提取和<code>slice</code>切片提取等布局调整接口，大幅简化多维数据的操作流程。相较于基础Tensor需要手动计算偏移地址、步长参数和搬运长度，扩展Tensor的接口可自动推导这些底层参数，开发者只需关注数据逻辑即可。这种抽象封装方式不仅降低了编程复杂度，也减少了参数配置错误的风险，让开发者能将精力集中于算子性能优化与算法实现，显著提升开发效率。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// Construct tensor for Global Memory</span>
<span class="k">auto</span><span class="w"> </span><span class="n">global_layout</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_layout</span><span class="p">(</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_shape</span><span class="p">(</span><span class="mi">128</span><span class="p">,</span><span class="w"> </span><span class="mi">256</span><span class="p">));</span>
<span class="k">auto</span><span class="w"> </span><span class="n">global_tensor</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_tensor</span><span class="p">(</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">gm_ptr</span><span class="p">),</span><span class="w"> </span><span class="n">global_layout</span><span class="p">);</span>

<span class="k">auto</span><span class="w"> </span><span class="n">sub_tensor</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">global_tensor</span><span class="p">.</span><span class="n">slice</span><span class="p">(</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="mi">32</span><span class="p">,</span><span class="w"> </span><span class="mi">64</span><span class="p">),</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_shape</span><span class="p">(</span><span class="mi">32</span><span class="p">,</span><span class="w"> </span><span class="mi">32</span><span class="p">));</span>
</code></pre></div><h3 id="矩阵搬运和计算">矩阵搬运和计算<a class="header-anchor" href="#矩阵搬运和计算">​</a></h3><p>基础搬运接口需手动传入<code>count</code>或<code>DataCopyParams</code>参数指定搬运长度和搬运模式。扩展Tensor携带Shape、Stride和存储位置信息，编译器自动推断部分搬运参数和物理通路，简化接口调用。同时提供<strong>Atom定制接口</strong>，开发者可基于<code>copy_traits</code>自定义搬运行为（如自定义搬运模式、随路处理等），满足特殊场景定制需求。</p><ul><li><strong>GM2L1搬运</strong>：<code>copy(atom, dst, src)</code>搬运矩阵数据到L1 Buffer，支持随路格式转换（ND2NZ、DN2NZ、NZ2NZ等）。开发者定义源Tensor和目的Tensor的Layout，并使用<code>make_copy</code>构造GM到L1 Buffer的搬运原子对象，接口自动推导底层搬运参数和格式转换方式。</li></ul><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// Construct GM-to-L1 copy_atom with the default trait</span>
<span class="k">auto</span><span class="w"> </span><span class="n">atom</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_copy</span><span class="p">(</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">copy_gm_to_l1</span><span class="p">{},</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">gm_to_l1_trait_default</span><span class="p">{});</span>

<span class="c1">// Copy equal-size tensors, and infer copy parameters from Layout</span>
<span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">copy</span><span class="p">(</span><span class="n">atom</span><span class="p">,</span><span class="w"> </span><span class="n">l1_tensor</span><span class="p">,</span><span class="w"> </span><span class="n">global_tensor</span><span class="p">);</span>

<span class="c1">// Specify Global Tensor offset to copy a slice from Global Tensor</span>
<span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">copy</span><span class="p">(</span><span class="n">atom</span><span class="p">,</span><span class="w"> </span><span class="n">l1_bias_tensor</span><span class="p">,</span>
<span class="w">    </span><span class="n">global_bias</span><span class="p">.</span><span class="n">slice</span><span class="p">(</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">j</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">base_n</span><span class="p">),</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_shape</span><span class="p">(</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="n">cur_n</span><span class="p">)));</span>
</code></pre></div><ul><li><strong>L0C2GM搬出</strong>：基于<code>copy_traits</code>定制随路处理（如Fixpipe量化），将L0C Buffer计算结果搬出至GM。</li></ul><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// Fixpipe inline quantization example</span>
<span class="kt">float</span><span class="w"> </span><span class="n">quant_value</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mf">0.5f</span><span class="p">;</span>
<span class="kt">uint64_t</span><span class="w"> </span><span class="n">quant_scalar</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">uint64_t</span><span class="o">&gt;</span><span class="p">(</span><span class="o">*</span><span class="k">reinterpret_cast</span><span class="o">&lt;</span><span class="kt">int32_t</span><span class="o">*&gt;</span><span class="p">(</span><span class="o">&amp;</span><span class="n">quant_value</span><span class="p">));</span>
<span class="k">auto</span><span class="w"> </span><span class="n">atom</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_copy</span><span class="p">(</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">copy_l0c_to_gm</span><span class="p">{},</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">l0c_to_gm_trait_default</span><span class="p">{})</span>
<span class="w">                </span><span class="p">.</span><span class="n">with</span><span class="p">(</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">l0c_to_gm_params</span><span class="p">{});</span>
<span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">copy</span><span class="p">(</span><span class="n">atom</span><span class="p">,</span><span class="w"> </span><span class="n">global_c</span><span class="p">,</span><span class="w"> </span><span class="n">l0c_tensor</span><span class="p">,</span><span class="w"> </span><span class="n">quant_scalar</span><span class="p">);</span>
</code></pre></div><p>同样，L1 Buffer到L0A/L0B Buffer的搬运需要构造对应通路的<code>copy_atom</code>，矩阵计算需要构造<code>mmad_atom</code>。开发者传入搬运或计算原子对象以及操作Tensor后，接口可根据Layout推导底层参数。</p><h3 id="基于扩展Tensor的矩阵计算示例">基于扩展Tensor的矩阵计算示例<a class="header-anchor" href="#基于扩展Tensor的矩阵计算示例">​</a></h3><p>结合上述矩阵计算的搬运与计算能力，开发者可基于C++ Tensor编程实现矩阵类算子。具体开发实践可参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/07_tensor_api/matmul_tensor_api/README.md">matmul实现样例</a>。</p></article></div>`,1)])])}const E=A(B,[["render",N]]);export{G as __pageData,E as default};
